 1→// The task report: how many tasks are done, per owner.
 2→//
 3→//   main(["tasks.json"], readFile) → the text table
 4→
 5→/** Counts tasks ({ title, owner, done }) in total and per owner. */
 6→export function summarize(tasks) {
 7→  const owners = {};
 8→  for (const task of tasks) {
 9→    const owner = (owners[task.owner] ??= { total: 0, done: 0 });
10→    owner.total++;
11→    if (task.done) owner.done++;
12→  }
13→  const done = tasks.filter((t) => t.done).length;
14→  return { total: tasks.length, done, open: tasks.length - done, owners };
15→}
16→
17→/** The summary as a table, one line per owner. */
18→export function formatText(summary) {
19→  const lines = [`${summary.done}/${summary.total} done, ${summary.open} open`];
20→  for (const [owner, counts] of Object.entries(summary.owners)) lines.push(`  ${owner.padEnd(10)} ${counts.done}/${counts.total}`);
21→  return lines.join("\n");
22→}
23→
24→/** argv: the tasks file's path. readFile(path) gives its text. */
25→export function main(argv, readFile) {
26→  const [file] = argv;
27→  if (!file) throw new Error("usage: report <tasks.json>");
28→  return formatText(summarize(JSON.parse(readFile(file))));
29→}
